referenceSolutions.javascript:
function pairedDrawersPeakTicket(drawers) {
  const a=drawers; let out=[];
  let i=0,j=0;while(i<a[0].length||j<a[1].length){if(j===a[1].length||(i<a[0].length&&a[0][i]<=a[1][j]))out.push(a[0][i++]);else out.push(a[1][j++]);}
  let answer=out.length?out[0]:0;for(const x of out)if(x>answer)answer=x;return answer;
}

