referenceSolutions.python:
def pairedDrawersPeakTicket(drawers):
    a=drawers
    out=[]
    i=j=0
    while i<len(a[0]) or j<len(a[1]):
        if j==len(a[1]) or (i<len(a[0]) and a[0][i]<=a[1][j]):
            out.append(a[0][i])
            i+=1
        else:
            out.append(a[1][j])
            j+=1
    return max(out,default=0)

